import { Link, useNavigate, useParams } from "react-router-dom";
import {
  ApiLoder,
  BackButton,
  ErrorMessage,
  HasPermission,
  JobUi,
  SuccessMessage,
} from "../../../helpers/common";
import Header from "../../../Layout/header";
import { useEffect, useRef, useState } from "react";
import { callAPI, callAPIWithoutAuth } from "../../../utils/apiUtils";
import { apiUrls } from "../../../utils/apiUrls";
import AddnewWindow from "./AddnewWindow";
import SimpleReactValidator from "simple-react-validator";
import { Window } from "../../../Redux/Redux/Action/Action";
import { useDispatch, useSelector } from "react-redux";
import JobTab from "../../Form/JobTab";
import Breakdown from "./Breakdown";
import { defaultConfig } from "../../../config";

export default function Index() {
  const [tenantList, setTenantList] = useState([]);
  const [coupan, setCoupan] = useState([]);
  const [Tax, setTax] = useState([]);
  const [cupondata, setCoupandata] = useState({});
  const [taxdata, setTaxdata] = useState({});
  const [list, setList] = useState({ WindowProductId: [] });
  const [loder, setLoader] = useState(0);
  const [open, setOpen] = useState(false);
  const [showTax, setShowTax] = useState(false);
  const [isview, setisview] = useState(false);
  const param = useParams();
  const [refresh, setRefresh] = useState(true);
  const [history, setHistory] = useState(false);
  const [object, setObject] = useState("");
  const [value, setValue] = useState({
    estimateName: "",
    termsCondition: "",
    notes: "",
    jobId: param.JobId,
    windowProductId: [],
    discountCoupon: null,
    discountId: null,
    subTotal: 0,
    tax: 0,
    discount: 0,
    grandTotal: 0,
    taxRateId: null,
    additionalCost: 0,
  });
  const simpleValidator = useRef(new SimpleReactValidator());
  const [, forceUpdate] = useState();
  const navigate = useNavigate();
  const handleChange = (e) => {
    setValue((val) => {
      return { ...val, [e.target.name]: e.target.value };
    });
  };
  const dispatch = useDispatch();

  const startLoading = () => setLoader((prev) => prev + 1);
  const stopLoading = () => setLoader((prev) => Math.max(0, prev - 1));

  const languageAdd = async (e) => {
    e.preventDefault();
    if(refresh){
    const formValid = simpleValidator.current.allValid();
    if (!formValid) {
      simpleValidator.current.showMessages();
      forceUpdate(1);
    } else {
      startLoading();
      try {
        const apiResponse = await callAPI(
          !param.estimateId ? apiUrls.EstimateCreate : apiUrls.EstimateUpdate,
          {},
          "POST",
          value
        );
        stopLoading();
        if (apiResponse?.data?.isSuccess) {
          dispatch(Window([]));
          localStorage.setItem("activeTab", "#estimate");
          SuccessMessage(apiResponse?.data?.message);
          navigate(`/contacts/job/${param.JobId}`);
        } else {
          ErrorMessage(apiResponse?.data?.message);
        }
      } catch (error) {
        stopLoading();
      }
    }
  }
  else{
    ErrorMessage("Please click the Refresh button, then submit."); 
  }
  };

  const TenantlistAPI = async () => {
    startLoading();
    let query = {
      tenantId: "",
      searchValue: param.JobId,
      pageNo: 1,
      recordPerPage: 10,
      status: 2,
      vendor: "",
      productType: "",
      jobStatus: "",
      address: "",
    };
    try {
      const apiResponse = await callAPI(apiUrls.Job, {}, "POST", query);
      stopLoading();
      if (apiResponse?.data?.isSuccess) {
        setTenantList(apiResponse?.data?.data);
        CouponlistAPI(apiResponse?.data?.data[0].contactId);
      } else {
        setTenantList([]);
        ErrorMessage(apiResponse?.data?.message);
      }
    } catch (error) {
      stopLoading();
    }
  };

  const BuildEstimate = async (windowProductId) => {
    startLoading();
    try {
      const apiResponse = await callAPIWithoutAuth(apiUrls.BuildEstimate, {}, "POST", {
        WindowProductIds: windowProductId,
        IsBreakDown: false,
      });
      stopLoading();
      if (apiResponse?.data?.isSuccess) {
        setShowTax(apiResponse?.data?.data[0]?.isTaxApplied);
        setList((val) => {
          return { ...val, WindowProductId: apiResponse?.data?.data };
        });
        const totalPriceSum = apiResponse?.data?.data.reduce(
          (sum, item) => sum + item.totalPrice,
          0
        );
        const additionalCost = apiResponse?.data?.data.reduce(
          (sum, item) => sum + item.additionalCost,
          0
        );
        setValue((val) => ({
          ...val,
          subTotal: parseFloat(totalPriceSum),
          grandTotal: parseFloat(totalPriceSum) + parseFloat(additionalCost),
          additionalCost: parseFloat(additionalCost),
          tax: 0,
          taxRateId: null,
          discount: 0,
          discountCoupon: null,
          discountId: null,
        }));
      } else {
        setValue((val) => ({
          ...val,
          subTotal: 0,
          grandTotal: 0,
          additionalCost: 0,
          tax: 0,
          taxRateId: null,
          discount: 0,
          discountCoupon: null,
          discountId: null,
        }));
       
      }
    } catch (error) {
      stopLoading();
    }
  };

  const EstimatelistAPI = async () => {
    startLoading();
    let query = {
      jobId: param.JobId,
      searchValue: "",
      estimationId:param.estimateId,
      pageNo: 1,
      recordPerPage: 10,
      status: 2,
      tenantId: "",
      vendor: "",
      productType: "",
      jobStatus: "",
      address: "",
      region: "",
    };

    try {
      const apiResponse = await callAPI(apiUrls.Estimate, {}, "POST", query);

      if (apiResponse?.data?.isSuccess) {
        let datas = apiResponse?.data?.data[0];
        setValue(datas);
        setShowTax(datas?.isTaxApplied);
        const transformedData = datas?.estimateProductList.map(
          (item, index) => {
            return {
              windowProdcutId: datas?.windowProductId[index],
              productName: item?.productName,
              productTypeName: item?.productTypeName,
              label: item?.label,
              height: item?.estimateWindowDetails?.height,
              width: item?.estimateWindowDetails?.width,
              archHeight: item?.estimateWindowDetails?.archHeight,
              options: item?.options,
              totalPrice: item?.totalPrice,
              quantity: item?.windowQty,
              isviewedit:true
            };
          }
        );
        setList((val) => {
          return { ...val, WindowProductId: transformedData };
        });
        stopLoading();
      } else {
        stopLoading();
        ErrorMessage(apiResponse?.data?.message);
      }
    } catch (error) {
      stopLoading();
    }
  };
  const windowsdata = useSelector((state) => state.Windowsadd.window);

  const CouponlistAPI = async (contactId) => {
    try {
      const apiResponse = await callAPI(
        apiUrls.GetAllDiscount,
        { CustomerId: contactId },
        "GET"
      );
      if (apiResponse?.data?.isSuccess) {
        setCoupan(apiResponse?.data?.data);
      } else {
        setCoupan([]);
        ErrorMessage(apiResponse?.data?.message);
      }
    } catch (error) {}
  };

  const TaxlistAPI = async () => {
    try {
      const apiResponse = await callAPI(apiUrls.GetAllTax, {}, "GET");
      if (apiResponse?.data?.isSuccess) {
        setTax(apiResponse?.data?.data);
      } else {
        setTax([]);
        ErrorMessage(apiResponse?.data?.message);
      }
    } catch (error) {}
  };

  const EstimationUniquename = async () => {
    startLoading();
    try {
      const apiResponse = await callAPI(apiUrls.EstimationUniquename, {}, "GET");
      stopLoading();
      if (apiResponse?.data?.isSuccess) {
        setValue((val) => {
          return { ...val, estimateName: apiResponse?.data?.data };
        });
      } else {
      
      }
    } catch (error) {stopLoading();}
  };

  useEffect(() => {
    TenantlistAPI();
    if (param.estimateId) {
      setRefresh(false)
      EstimatelistAPI();
    }
    if (!param.estimateId) {
      EstimationUniquename();
    }

    if (windowsdata?.length > 0) {
      const ids = windowsdata.map((item) => item.windowProductId);
      setValue((val) => {
        return {
          ...val,
          windowProductId: [...(val.windowProductId || []), ...ids],
        };
      });

      BuildEstimate(ids);
    }
    TaxlistAPI();
    // eslint-disable-next-line
  }, []);

  const handleSenddata = (data) => {
    const ids = data.map((item) => item.windowProductId);
    setValue((val) => {
      return {
        ...val,
        windowProductId: [...(val.windowProductId || []), ...ids],
      };
    });

    BuildEstimate([...(value.windowProductId || []), ...ids]);
  };

  const handledeletedata = (data) => {
    setValue((val) => {
      return {
        ...val,
        windowProductId: (val.windowProductId || []).filter(
          (item) => item !== data.windowProdcutId
        ),
      };
    });
    setList((val) => {
      return {
        ...val,
        WindowProductId: (val.WindowProductId || []).filter(
          (item) => item !== data
        ),
      };
    });
    BuildEstimate((value.windowProductId || []).filter(
      (item) => item !== data.windowProdcutId
    ));
   
    //   ...val,
    //   subTotal: parseFloat(
    //     Math.max(0, Number(val.subTotal) - Number(data?.totalPrice || 0))
    //   ),
    //   grandTotal: parseFloat(
    //     Math.max(
    //       0,
    //       Number(val.subTotal) -
    //         Number(data?.totalPrice || 0) -
    //         Number(data?.additionalCost || 0)
    //     )
    //   ),
    //   additionalCost: parseFloat(
    //     Math.max(
    //       0,
    //       Number(val.additionalCost) - Number(data?.additionalCost || 0)
    //     )
    //   ),
    //   tax: 0,
    //   taxRateId: null,
    //   discount: 0,
    //   discountCoupon: null,
    //   discountId: null,
    // }));
  };

  const handleChangecupan = (e) => {
    if (e.target.value) {
      setCoupandata(JSON.parse(e.target.value));
    } else {
      setValue((val) => ({
        ...val,
        grandTotal:
          value?.subTotal + Number(value?.additionalCost) + value.tax || 0,
        discount: 0,
        discountCoupon: null,
        discountId: null,
      }));
      setCoupandata({});
    }
  };
  const Applycopan = () => {
    if (
      cupondata &&
      (cupondata.discountTypeName ||
        cupondata.fixedAmount ||
        cupondata.percentageDiscount)
    ) {
      let discount = 0;
      let grandTotal = 0;
      if (cupondata?.discountTypeName === "Fixed") {
        discount =
          Number(cupondata?.fixedAmount) > Number(value.subTotal)+ Number(value?.additionalCost)
            ? Number(value.subTotal) + Number(value?.additionalCost)
            : Number(cupondata?.fixedAmount);
        grandTotal = Math.max(
          0,
          value.subTotal + value.tax + Number(value?.additionalCost) - discount
        );
      } else if (cupondata?.discountTypeName === "Percentage") {
        discount =
          ((value.subTotal + Number(value?.additionalCost)) * Number(cupondata?.percentageDiscount)) / 100;
        grandTotal = Math.max(
          0,
          ((value.subTotal + Number(value?.additionalCost)) - discount) + value.tax  
        );
      }
      setValue((val) => ({
        ...val,
        grandTotal: Number(grandTotal),
        discount: Number(discount),
        discountCoupon: cupondata?.couponCode,
        discountId: cupondata?.discountId,
      }));
      SuccessMessage(
        `Applied coupon code ${cupondata?.couponCode} successfully!`
      );
    }
  };

  const handleChangetax = (e) => {
    if (e.target.value) {
      setTaxdata(JSON.parse(e.target.value));
    } else {
      setValue((val) => ({
        ...val,
        grandTotal:
          value?.subTotal + Number(value?.additionalCost) - value.discount || 0,
        tax: 0,
        taxRateId: null,
      }));
      setTaxdata({});
    }
  };

  const Applytax = () => {
    if (taxdata && taxdata.taxRateId) {
      let tax = 0;
      let grandTotal = 0;

      tax = Math.max(0, ((value.subTotal + Number(value?.additionalCost) - value.discount) * Number(taxdata?.rate)) / 100);
      grandTotal = Math.max(
        0,
        value.subTotal - value.discount + tax + Number(value?.additionalCost)
      );

      setValue((val) => ({
        ...val,
        grandTotal: Number(grandTotal),
        tax: Number(tax),
        taxRateId: taxdata?.taxRateId,
      }));
      SuccessMessage(`Applied tax ${taxdata?.rate} successfully!`);
    }
  };

  const Refresh = ()=>{
    setRefresh(true)
    BuildEstimate(value?.windowProductId||[]);
  }

  return (
    <>
      {loder > 0 && <ApiLoder />}
      <div className="intersight_content">
       <Header title={`Contacts / ${tenantList[0]?.contactFirstName + " " + tenantList[0]?.contactLasttName}`} />
        <div className="body_content">
          <div className="contact-profile">
            <div className="engage-tabs">
              <ul className="nav nav-pills" id="pills-tab" role="tablist">
                <JobTab contactId={tenantList[0]?.contactId} />
              </ul>
              <div className="tab-content" id="pills-tabContent">
                <div className="row mb-30">
                  <BackButton link={`/contacts/job/${tenantList[0]?.jobId}`} />
                  <div className="col-lg-12">
                    <div className="new-job_list">
                      <JobUi tenantList={tenantList[0]} />
                    </div>
                  </div>
                </div>
                <div className="d-block d-md-flex align-items-center justify-content-between mb-30">
                  <div className="heading_width_search d-flex align-items-center gap-3 margin-for-mobile">
                    <h2 className="body_heading width-left-border mb-0">
                      {param.estimateId ? "Update" : "Create"} Estimate{" "}
                      <sup className="boldsup">*</sup>
                    </h2>
                    <div className="estimate-input">
                      <input
                        type="text"
                        placeholder="Enter Estimate Title"
                        name="estimateName"
                        onChange={handleChange}
                        value={value?.estimateName}
                      />

                      <div className="error">
                        {simpleValidator.current.message(
                          "Estimate Title",
                          value?.estimateName,
                          `required`
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="heading_width_search d-flex align-items-center gap-3">
                    <Link
                      to="#"
                      className="btn blue-outline-btn small_btn"
                      onClick={() => setOpen(true)}
                    >
                      Add Window
                    </Link>
                    {param.estimateId &&
                    <Link
                      to="#"
                      className="btn blue-outline-btn small_btn"
                      onClick={() => Refresh()}
                    >
                      Refresh
                    </Link>
}
                  </div>
                </div>
                <div className="estimate-table task_table mb-30">
                  <div className="table-responsive">
                    <table className="table">
                      <thead>
                        <tr>
                          <th scope="col">Window label</th>
                          <th scope="col">Window Qty</th>
                          <th scope="col">Product Type</th>
                          <th scope="col">Product</th>
                          <th scope="col">Dimension</th>
                          <th scope="col">Options</th>
                          <th scope="col" className=" text-center">
                            Price
                          </th>
                          <th scope="col" className=" text-center">
                            Breakdown
                          </th>

                          <th scope="col" className=" text-center">
                            Delete
                          </th>
                        </tr>
                      </thead>
                      <tbody>
                        {list?.WindowProductId?.map((val, i) => (
                          <tr key={i}>
                            <td>{val?.label}</td>
                            <td>{val?.quantity}</td>
                            <td>{val?.productTypeName}</td>
                            <td>{val?.productName}</td>
                            <td>
                              W: {val?.width}”, H: {val?.height}”, A:{" "}
                              {val?.archHeight}”
                            </td>
                            <td>
                              <span>
                                <ul className="colors">
                                  {val?.options?.map((vals, ind) => (
                                    <li className="color-item" key={ind}>
                                      {vals}
                                    </li>
                                  ))}
                                </ul>
                              </span>
                            </td>
                            <td className=" text-center">
                              {defaultConfig.currencySign} {val?.totalPrice}
                            </td>
                            <td
                              className="text-center"
                              onClick={() => {
                                setisview(val?.isviewedit?true:false)
                                setHistory(true);
                                setObject(val);
                               
                              }}
                            >
                              <Link to="#">
                                {" "}
                                <img src="/image/breakdown.svg" alt="" loading="lazy"/>
                              </Link>
                            </td>

                            <td
                              className="text-center"
                              onClick={() => handledeletedata(val)}
                            >
                              <span style={{ cursor: "pointer" }}>
                                <img src="/image/deleteblue.svg" alt="" loading="lazy"/>
                              </span>
                            </td>
                          </tr>
                        ))}

                        {list?.WindowProductId?.length === 0 && (
                          <tr>
                            <td
                              className="text-center border-0 no-records"
                              colSpan={9}
                            >
                              <img
                                src="/image/no-records.svg"
                                alt=" "
                                loading="lazy"
                                className="img-fluid"
                              />
                              <p className="font-14">
                                Please add a window to create a Estimate
                              </p>
                            </td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                    <div className="error">
                      {simpleValidator.current.message(
                        "Windows",
                        value?.windowProductId,
                        `required`
                      )}
                    </div>
                  </div>
                </div>
                <div className="row">
                  <div className="col-md-6" />
                  <div className="col-md-6">
                    <div className="adjust-pricing">
                      <div className="middle-heading">
                        <h4>Adjust Pricing</h4>
                      </div>
                      <div className="couponinput mb-2">
                        <div className="d-flex align-items-center justify-content-between w-100">
                          <select
                            className="form-select null"
                            onChange={handleChangecupan}
                          >
                            <option value="">
                              Discount coupon  (e.g., promotional discounts,
                              bulk order...
                            </option>
                            {coupan?.map((val, i) => (
                              <option
                                value={JSON.stringify(val)}
                                key={i}
                                selected={
                                  value.discountCoupon === val?.couponCode
                                    ? true
                                    : false
                                }
                              >
                                {val?.couponCode} ({val?.discountTypeName} -{" "}
                                {val?.discountTypeName === "Percentage"
                                  ? val?.percentageDiscount
                                  : val?.fixedAmount}
                                )
                              </option>
                            ))}
                          </select>

                          <button
                            type="button"
                            className="btn blue-btn small_btn"
                            onClick={Applycopan}
                          >
                            Apply
                          </button>
                        </div>
                      </div>
                      {!showTax && (
                        <div className="couponinput mb-3">
                          <div className="d-flex align-items-center justify-content-between w-100">
                            <select
                              className="form-select null"
                              onChange={handleChangetax}
                            >
                              <option value="">Apply Tax</option>
                              {Tax?.map((val, i) => (
                                <option
                                  value={JSON.stringify(val)}
                                  key={i}
                                  selected={
                                    value.taxRateId === val?.taxRateId
                                      ? true
                                      : false
                                  }
                                >
                                  {val?.regionName} ( {val?.rate})
                                </option>
                              ))}
                            </select>

                            <button
                              type="button"
                              className="btn blue-btn small_btn"
                              onClick={Applytax}
                            >
                              Apply
                            </button>
                          </div>
                        </div>
                      )}
                      <div className="price-content w-100">
                        <div className="price-content-inner">
                          <div className="d-flex justify-content-between">
                            <h2 className="font-14 mb-0">Subtotal:</h2>
                            <span className="mb-0">
                              {defaultConfig.currencySign}{" "}
                              {Number(value?.subTotal)?.toFixed(2)}
                            </span>
                          </div>
                          <div className="d-flex justify-content-between">
                            <h2 className="font-14 mb-0">Additional Cost:</h2>
                            <span className="mb-0">
                              {defaultConfig.currencySign}{" "}
                              {Number(value?.additionalCost)?.toFixed(2)}
                            </span>
                          </div>
                          <div className="d-flex justify-content-between">
                            <h2 className="font-14 mb-0">Discount:</h2>
                            <span className="mb-0">
                              {defaultConfig.currencySign}{" "}
                              {Number(value?.discount)?.toFixed(2)}
                            </span>
                          </div>
                          <div className="d-flex justify-content-between">
                            <h2 className="font-14 mb-0">Taxes:</h2>
                            <span className="mb-0">
                              {defaultConfig.currencySign}{" "}
                              {Number(value?.tax)?.toFixed(2)}
                            </span>
                          </div>
                         
                          <div className="d-flex justify-content-between">
                            <h2 className="font-14 mb-0">Grand Total:</h2>
                            <span className="mb-0">
                              {defaultConfig.currencySign}{" "}
                              {Number(value?.grandTotal)?.toFixed(2)}
                            </span>
                          </div>
                        </div>
                      </div>
                      <div className="middle-heading">
                        <h4>Estimate Notes</h4>
                      </div>
                      <div className="row ">
                        <div className="col-md-6 mb-3">
                          <h2 className="font-14">Terms and Conditions</h2>
                          <div className="terms-content">
                            <textarea
                              className="form-control"
                              placeholder="payment terms, warranty information, and any disclaimers"
                              name="termsCondition"
                              onChange={handleChange}
                              value={value?.termsCondition}
                            />
                          </div>
                        </div>
                        <div className="col-md-6 mb-3">
                          <h2 className="font-14">Additional Notes</h2>
                          <div className="terms-content">
                            <textarea
                              className="form-control"
                              placeholder="Add any other relevant information for the customer"
                              name="notes"
                              onChange={handleChange}
                              value={value?.notes}
                            />
                          </div>
                        </div>
                      </div>
                      <div className="form-style form-group d-flex align-items-center justify-content-end w-100">
                        <Link
                          to={`/contacts/job/${tenantList[0]?.jobId}`}
                          className="cancel text-decoration-underline"
                        >
                          Cancel
                        </Link>
                        {HasPermission("EstimateAdd") && (
                          <Link
                            to="#"
                            className="btn blue-btn"
                            onClick={languageAdd}
                          >
                            {param.estimateId ? "Update" : "Save"}
                          </Link>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <AddnewWindow
        open={open}
        handleclose={() => setOpen(false)}
        jobid={param.JobId}
        handleSenddata={handleSenddata}
        Addedwindows={list.WindowProductId}
        listdata={tenantList[0]}
      />
      <Breakdown
        open={history}
        handleClose={() => setHistory(false)}
        data={object}
        EstimateId={param.estimateId?param.estimateId:""}
        IsView={isview}
      />
    </>
  );
}
